select component_type_cd, update_ts, update_user_id, delete_sw 
	from tb_ive_component_status 
where event_id in
		( select event_id
			from tb_eligibility_events 
		where eligibility_period_id  
			in ( select eligibility_period_id
					from tb_eligibility_period 
				where eligibility_id 
					in ( 	10003584, 10003499, 10003513, 10003592, 10003645, 10005506, 10003521, 10003590, 10003589, 10003512,
							10004066, 10004199, 10005041, 10003943, 10003998, 10003672, 10000668, 10000729, 10005264, 10004173,
							10004679, 10003311, 10003292, 10003293, 10003547, 10003847, 10003932, 10004382, 10004956, 10005338,
							10005235, 10005236, 10005297, 10005587, 10003233, 10003234, 10005619, 10005174, 10005035, 10004675,
							10004489, 10004574, 10001782, 10003536, 10004031 
						)	
					and delete_sw  = 'N'
				)
		)
	and delete_sw = 'N' ;


update tb_ive_component_status
set delete_sw = 'Y',
	update_user_id = 'CIDM-5517',
	update_ts = now()
where event_id in
		( select event_id
			from tb_eligibility_events 
		where eligibility_period_id  
			in ( select eligibility_period_id
					from tb_eligibility_period 
				where eligibility_id 
					in ( 	10003584, 10003499, 10003513, 10003592, 10003645, 10005506, 10003521, 10003590, 10003589, 10003512,
							10004066, 10004199, 10005041, 10003943, 10003998, 10003672, 10000668, 10000729, 10005264, 10004173,
							10004679, 10003311, 10003292, 10003293, 10003547, 10003847, 10003932, 10004382, 10004956, 10005338,
							10005235, 10005236, 10005297, 10005587, 10003233, 10003234, 10005619, 10005174, 10005035, 10004675,
							10004489, 10004574, 10001782, 10003536, 10004031 
						)	
					and delete_sw  = 'N'
				)
		)
	and delete_sw = 'N' ;	


